import { useEffect, useRef, useCallback, useState } from 'react';

function useWebSocket(authToken) {
  const [isConnected, setIsConnected] = useState(false);
  const [messages, setMessages] = useState([]);
  const wsRef = useRef(null);
  const reconnectAttempts = useRef(0);
  const reconnectTimer = useRef(null);
  const isMountedRef = useRef(true);

  const connect = useCallback(() => {
    // Don't open a new connection if one is already open
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) return;

    const ws = new WebSocket(`wss://api.myapp.com/ws?token=${authToken}`);
    wsRef.current = ws;

    ws.onopen = () => {
      if (!isMountedRef.current) return;
      setIsConnected(true);
      reconnectAttempts.current = 0;
    };

    ws.onmessage = (event) => {
      if (!isMountedRef.current) return;
      try {
        const data = JSON.parse(event.data);
        setMessages(prev => [...prev, data]);
      } catch (err) {
        console.error('Failed to parse WebSocket message:', err);
      }
    };

    ws.onerror = (err) => {
      console.error('WebSocket error:', err);
      if (!isMountedRef.current) return;
      setIsConnected(false);
    };

    ws.onclose = (event) => {
      if (!isMountedRef.current) return;
      setIsConnected(false);

      // Don't reconnect if closed cleanly (code 1000) or token is gone
      if (event.code === 1000 || !authToken) return;

      const delay = Math.min(1000 * 2 ** reconnectAttempts.current, 30000);
      console.log(`Reconnecting in ${delay}ms (attempt ${reconnectAttempts.current + 1})`);

      reconnectTimer.current = setTimeout(() => {
        reconnectAttempts.current += 1;
        connect();
      }, delay);
    };
  }, [authToken]);

  useEffect(() => {
    isMountedRef.current = true;
    connect();

    return () => {
      isMountedRef.current = false;

      // Cancel any pending reconnect timer
      if (reconnectTimer.current) {
        clearTimeout(reconnectTimer.current);
        reconnectTimer.current = null;
      }

      // Close the socket cleanly
      if (wsRef.current) {
        wsRef.current.onclose = null; // Prevent the onclose from scheduling another reconnect
        wsRef.current.close(1000, 'Component unmounted');
        wsRef.current = null;
      }
    };
  }, [connect]);

  return { isConnected, messages };
